// ─── File: loader/PluginClassLoader.java ───
package com.bank.plugin.loader;

import java.io.*;
import java.nio.file.*;

// A child class loader that loads plugin classes from a specific directory.
// It delegates to its parent first (for core/shared classes), then loads
// the plugin's own classes locally — the identity of those classes becomes
// (name + THIS loader), so two loaders give two distinct classes.
public class PluginClassLoader extends ClassLoader {
    private final Path pluginDir;

    public PluginClassLoader(String name, Path pluginDir, ClassLoader parent) {
        super(name, parent);                 // named child loader, parent set
        this.pluginDir = pluginDir;
    }

    @Override
    protected Class<?> findClass(String fqName) throws ClassNotFoundException {
        // Called only if the PARENT could not load the class (delegation model).
        try {
            Path classFile = pluginDir.resolve(fqName.replace('.', '/') + ".class");
            byte[] bytes = Files.readAllBytes(classFile);
            return defineClass(fqName, bytes, 0, bytes.length);  // THIS loader defines it
        } catch (IOException e) {
            throw new ClassNotFoundException(fqName, e);
        }
    }
}
