// ─── File: ClassLoaderDemo.java ───
package com.bank.plugin;

import com.bank.plugin.loader.PluginClassLoader;
import java.nio.file.*;
import java.util.logging.*;

public class ClassLoaderDemo {
    private static final Logger log = Logger.getLogger(ClassLoaderDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        ClassLoader app = ClassLoaderDemo.class.getClassLoader();

        // Show the delegation hierarchy for THIS class.
        log.info(() -> "Application loader : " + app);
        log.info(() -> "Its parent (Platform): " + app.getParent());
        log.info(() -> "Platform's parent (Bootstrap) is null: " + (app.getParent().getParent() == null));

        // Two plugins, each with its OWN FeePolicy class of the SAME fq-name,
        // compiled into two different directories (plugin-a, plugin-b).
        var loaderA = new PluginClassLoader("plugin-a", Paths.get("plugins/a"), app);
        var loaderB = new PluginClassLoader("plugin-b", Paths.get("plugins/b"), app);

        Class<?> feeA = Class.forName("com.bank.ext.FeePolicy", true, loaderA);
        Class<?> feeB = Class.forName("com.bank.ext.FeePolicy", true, loaderB);

        // SAME name, DIFFERENT loaders → DISTINCT classes in the one JVM.
        log.info(() -> "feeA name: " + feeA.getName() + " loader: " + feeA.getClassLoader().getName());
        log.info(() -> "feeB name: " + feeB.getName() + " loader: " + feeB.getClassLoader().getName());
        log.info(() -> "feeA == feeB ? " + (feeA == feeB));   // false — different Class objects

        // Each plugin computes Rajesh/Priya fees with its own logic (reflectively invoked).
        Object policyA = feeA.getDeclaredConstructor().newInstance();
        Object policyB = feeB.getDeclaredConstructor().newInstance();
        var m = feeA.getMethod("feeFor", String.class);
        log.info(() -> "Plugin A fee for SAV2001 (Rajesh): Rs." + invoke(m, policyA, "SAV2001"));
        var m2 = feeB.getMethod("feeFor", String.class);
        log.info(() -> "Plugin B fee for CUR3001 (Priya) : Rs." + invoke(m2, policyB, "CUR3001"));

        // Casting an instance from loaderB to the class from loaderA would throw
        // ClassCastException: "FeePolicy cannot be cast to FeePolicy" — distinct types.
    }

    private static Object invoke(java.lang.reflect.Method m, Object target, Object arg) {
        try { return m.invoke(target, arg); } catch (Exception e) { throw new RuntimeException(e); }
    }
}
